package com.servicerca.service; import com.servicerca.dto.profile.*;import com.servicerca.dto.user.*;import com.servicerca.exception.BusinessException;import com.servicerca.mapper.ApiMapper;import com.servicerca.model.User;import com.servicerca.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class ProfileService{private final UserRepository users;private final TradeRepository trades;private final CryptoService crypto;private final ApiMapper mapper;public ProfileService(UserRepository u,TradeRepository t,CryptoService c,ApiMapper m){users=u;trades=t;crypto=c;mapper=m;}@Transactional(readOnly=true)public UserResponse get(User u){return mapper.toUserResponse(users.findById(u.getId()).orElseThrow());}@Transactional public UserResponse update(User principal,UpdateProfileRequest r){var u=users.findById(principal.getId()).orElseThrow();u.setFullName(r.fullName());u.setDniEncrypted(crypto.encrypt(r.dni()));u.setPhone(r.phone());u.setPhotoUrl(r.photoUrl());u.setLocality(r.locality().trim());u.setLatitude(r.latitude());u.setLongitude(r.longitude());u.setProfessionalEnabled(r.professionalEnabled());u.getTrades().clear();if(r.professionalEnabled()){u.getTrades().addAll(trades.findAllById(Objects.requireNonNullElse(r.tradeIds(),Set.of())));if(u.getTrades().isEmpty())throw new BusinessException("TRADE_REQUIRED","Elegí al menos un oficio.");}u.setOnboardingComplete(true);return mapper.toUserResponse(u);}@Transactional public UserResponse availability(User p,UpdateAvailabilityRequest r){var u=users.findById(p.getId()).orElseThrow();u.setAvailable(r.available());return mapper.toUserResponse(u);}}
